   "faqs": [{"q": "Should an automated reply count as the first response?", "a": "No. Count it as receipt confirmation only. A first response should contain an owner, a next action, and a due point so the requester knows what happens next."}, {"q": "How long should the team keep raw response timestamps?", "a": "Keep them long enough to reproduce a monthly review and compare shifts, then follow the client's retention schedule. Store the queue identifier rather than unnecessary personal content."}]
